// Pixel data of the living relief (dependency-free so it can run in a Web Worker).
// Same algorithm as the approved relief: the generated bytes are identical.
export const RELIEF_SIZE = 512;
export type ReliefData = { packed: Uint8Array; albedo: Uint8Array };

const clamp = (value: number, min: number, max: number) => Math.max(min, Math.min(max, value));

/** Seamless (periodic) value noise → domain-warped ridged fbm. Generated once per page. */
export function buildReliefData(): ReliefData {
  const SIZE = RELIEF_SIZE;
  // Perf: the lattice value of each (x, y, period) is computed once and looked up afterwards
  // (the original recomputed Math.sin millions of times). Same formula, same bytes.
  const lattices = new Map<number, Float64Array>();
  const lattice = (p: number) => {
    let table = lattices.get(p);
    if (!table) {
      table = new Float64Array(p * p);
      for (let y = 0; y < p; y++)
        for (let x = 0; x < p; x++) {
          const s = Math.sin(x * 127.1 + y * 311.7 + p * 17.3) * 43758.5453;
          table[y * p + x] = s - Math.floor(s);
        }
      lattices.set(p, table);
    }
    return table;
  };
  const hash = (x: number, y: number, p: number) =>
    lattice(p)[(((y % p) + p) % p) * p + (((x % p) + p) % p)]!;
  const noise = (x: number, y: number, p: number) => {
    const ix = Math.floor(x),
      iy = Math.floor(y),
      fx = x - ix,
      fy = y - iy,
      ux = fx * fx * (3 - 2 * fx),
      uy = fy * fy * (3 - 2 * fy);
    const a = hash(ix, iy, p),
      b = hash(ix + 1, iy, p),
      c = hash(ix, iy + 1, p),
      d = hash(ix + 1, iy + 1, p);
    return a + (b - a) * ux + (c - a) * uy + (a - b - c + d) * ux * uy;
  };
  const fbm = (x: number, y: number, base: number, octaves: number, ridged: boolean) => {
    let sum = 0,
      amp = 0.5,
      norm = 0,
      period = base;
    for (let o = 0; o < octaves; o++) {
      let n = noise(x * period, y * period, period);
      if (ridged) {
        n = 1 - Math.abs(n * 2 - 1);
        n *= n;
      }
      sum += n * amp;
      norm += amp;
      amp *= 0.5;
      period *= 2;
    }
    return sum / norm;
  };
  const height = new Float32Array(SIZE * SIZE);
  for (let j = 0; j < SIZE; j++)
    for (let i = 0; i < SIZE; i++) {
      const u = i / SIZE,
        v = j / SIZE;
      // Gravitational / fluvial warp: periodic offsets keep the tile seamless.
      const wx = fbm(u, v, 3, 3, false) - 0.5,
        wy = fbm(u + 0.37, v + 0.71, 3, 3, false) - 0.5;
      const ridges = fbm(u + wx * 0.22, v + wy * 0.22, 4, 5, true);
      const mass = fbm(u + wy * 0.1, v - wx * 0.1, 2, 3, false);
      height[j * SIZE + i] = ridges * 0.72 + mass * 0.28;
    }
  // Curvature = height − local mean (crests > 0, cavities < 0). Separable periodic box blur.
  const blur = (src: Float32Array, r: number) => {
    const tmp = new Float32Array(src.length),
      out = new Float32Array(src.length),
      k = 1 / (2 * r + 1);
    for (let j = 0; j < SIZE; j++)
      for (let i = 0; i < SIZE; i++) {
        let s = 0;
        for (let o = -r; o <= r; o++) s += src[j * SIZE + ((i + o + SIZE) % SIZE)]!;
        tmp[j * SIZE + i] = s * k;
      }
    for (let j = 0; j < SIZE; j++)
      for (let i = 0; i < SIZE; i++) {
        let s = 0;
        for (let o = -r; o <= r; o++) s += tmp[((j + o + SIZE) % SIZE) * SIZE + i]!;
        out[j * SIZE + i] = s * k;
      }
    return out;
  };
  const mean = blur(height, 7);
  const packed = new Uint8Array(SIZE * SIZE * 4),
    at = (i: number, j: number) => height[((j + SIZE) % SIZE) * SIZE + ((i + SIZE) % SIZE)]!;
  for (let j = 0; j < SIZE; j++)
    for (let i = 0; i < SIZE; i++) {
      const dx = (at(i + 1, j) - at(i - 1, j)) * 9,
        dy = (at(i, j + 1) - at(i, j - 1)) * 9,
        inv = 1 / Math.hypot(dx, dy, 1),
        o = (j * SIZE + i) * 4;
      packed[o] = Math.round((-dx * inv * 0.5 + 0.5) * 255);
      packed[o + 1] = Math.round((-dy * inv * 0.5 + 0.5) * 255);
      packed[o + 2] = Math.round(clamp(at(i, j), 0, 1) * 255);
      packed[o + 3] = Math.round(clamp((at(i, j) - mean[j * SIZE + i]!) * 4 + 0.5, 0, 1) * 255);
    }
  // Dark mineral albedo of the same surface, used inside the environment map so the sphere reflects it.
  const albedo = new Uint8Array(SIZE * SIZE * 4);
  for (let k = 0; k < SIZE * SIZE; k++) {
    const v = clamp(0.07 + height[k]! * 0.2 + (height[k]! - mean[k]!) * 0.9, 0, 0.45);
    albedo[k * 4] = Math.round(v * 236);
    albedo[k * 4 + 1] = Math.round(v * 246);
    albedo[k * 4 + 2] = Math.round(v * 255);
    albedo[k * 4 + 3] = 255;
  }
  return { packed, albedo };
}
